const items = $input.all();
const tickets = items[0]?.json || [];
const ticketList = Array.isArray(tickets) ? tickets : [tickets];

const statusMap = { 2: 'Open', 3: 'Pending', 4: 'Resolved', 5: 'Closed' };
const priorityMap = { 1: 'Low', 2: 'Medium', 3: 'High', 4: 'Urgent' };

let byStatus = {};
let byPriority = {};
let total = ticketList.length;

ticketList.forEach(ticket => {
  const status = statusMap[ticket.status] || 'Unknown';
  const priority = priorityMap[ticket.priority] || 'Unknown';
  byStatus[status] = (byStatus[status] || 0) + 1;
  byPriority[priority] = (byPriority[priority] || 0) + 1;
});

return [{
  json: {
    date: new Date().toISOString(),
    totalTickets: total,
    open: byStatus['Open'] || 0,
    pending: byStatus['Pending'] || 0,
    resolved: byStatus['Resolved'] || 0,
    closed: byStatus['Closed'] || 0,
    lowPriority: byPriority['Low'] || 0,
    mediumPriority: byPriority['Medium'] || 0,
    highPriority: byPriority['High'] || 0,
    urgentPriority: byPriority['Urgent'] || 0,
    statusSummary: JSON.stringify(byStatus),
    prioritySummary: JSON.stringify(byPriority)
  }
}];

